#include <vector>
#include <cstddef>
#include <omp.h>

/* Factorize the matrix A into A=LU where L is a lower triangular matrix and U is an upper triangular matrix.
   Store the results for L and U into the original matrix A.
   A is an NxN matrix stored in row-major.
   Use OpenMP to compute in parallel.
   Example:

   input: [[4, 3], [6, 3]]
   output: [[4, 3], [1.5, -1.5]]
*/
void luFactorize(std::vector<double> &A, size_t N) {
    if (N == 0) return;

    // In-place Doolittle LU (without pivoting):
    // U is stored on and above diagonal, L is stored below diagonal with implicit 1s on diagonal.
    for (size_t k = 0; k < N; ++k) {
        const double pivot = A[k * N + k];

        // Compute multipliers for column k (L entries below diagonal).
        // Each thread writes a distinct A[i, k].
        #pragma omp parallel for schedule(static)
        for (std::ptrdiff_t i = static_cast<std::ptrdiff_t>(k) + 1; i < static_cast<std::ptrdiff_t>(N); ++i) {
            A[static_cast<size_t>(i) * N + k] /= pivot;
        }

        // Update trailing submatrix: A[i,j] -= A[i,k] * A[k,j], for i,j > k.
        // Each thread writes a distinct row i (and thus distinct A[i,j] elements).
        #pragma omp parallel for schedule(static)
        for (std::ptrdiff_t i = static_cast<std::ptrdiff_t>(k) + 1; i < static_cast<std::ptrdiff_t>(N); ++i) {
            const double lik = A[static_cast<size_t>(i) * N + k];
            const size_t rowBase = static_cast<size_t>(i) * N;
            const size_t kBase = k * N;
            for (size_t j = k + 1; j < N; ++j) {
                A[rowBase + j] -= lik * A[kBase + j];
            }
        }
    }
}
